      "raw_content": "카페홈\n좌담회/설문/주부알바\n가입\n검색\n메뉴\n▶설문 신청(당일 현금)~아시분과 신청가능\n앱 열기\n▶추후협의)시니어 건강음료 섭취자(파우더/액상) 설문 / 만50-69세 남여\n본문 기타 기능\n하늘\n카페매니저\n채팅\n작성일\n2026.10.01. 14:52\n조회 164\n▶추후협의)시니어 건강음료 섭취자(파우더/액상) 설문 / 만50-69세 남여\n=====================================\n본조사는 국내 유명 식품 회사에서 출시하는 식품에 대한 평가를 포함 하고 있습니다.\n본조사의 시식 제품 중 생산 설비가 갖춰진 곳에서 생산되지 않은 연구소 제조 테스트 제품이 포함 되어 있을수 있습니다.\n시식이 불편 하시다면 본 조사의 참여가 불가 합니다.\n장소:글로벌리서치 3층(서초구서초동)\n참석비:30000원\n-------------------------------------------------------------------\n▶기재 사항\n-->드시는 건강음료 제품명(파우더/액상)\n-------------------------------------------------------------------\n==>소개자란에 [김현숙]을 기재해야 신청 됩니다\n[아래 URL에 (클릭!!)하여 설문 진행해주세요.(스마트폰도 가능)\nhttps://forms.gle/eTVSRFjWmBwELM2m6\n좋아요\n0\n'좋아요'로 마음을 나누세요!\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n지금 가입하고 댓글에 참여해보세요!\n전체글\n▶10/13~11/6)각 분야 전문가 인터뷰\n하늘\n26.10.01.\n댓글\n0\n▶추후협의)시니어 건강음료 섭취자(파우더/액상) 설문 / 만50-69세 남여\n하늘\n26.10.01.\n댓글\n0\n▶10/12~)구강 관련 제품 테스터/ 만 20~60세 남녀\n하늘\n26.10.01.\n댓글\n0\n▶10/14~15)스킨케어 관련 좌담회/ 만19세 ~45세 여성\n하늘\n26.10.01.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
