      "target_condition": "으로 온라인 인터뷰를 진행하고 있습니다. 아래 내용에 해당되시면 신청해 주시면 고맙겠습니다.",
      "date": "10/12(월) ~ 10/18(일) 중 하루 진행 / 시간은 추후 안내드립니다",
      "time": "",
