      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n10/9~10)만 30세~64세 남여) 24년 8월 이후 준대형 신차 구입하신 분\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.01. 14:25\n조회 68\n구독\n10/9~10)만 30세~64세 남여) 24년 8월 이후 준대형 신차 구입하신 분\n이번 저희 회사에서는 24년 8월 이후 준대형 신차 구입하신 분 대상 조사가 있습니다.\n그랜저, G80, K8 차량이 많이 부족합니다!\n많은 신청 부탁 드립니다.\n* 최근 1년 내 구입자 우선 리쿠르팅\n신청하신분은 재신청 안하셔도 됩니다\n저희는 휴메인리서치라는 설문조사 회사 입니다.\n이번 저희 회사에서는 24년 8월 이후 준대형 신차 구입하신 분 대상 조사가 있습니다.\n<공통조건>\n1. 만 30세~64세 남여\n2. 24년 8월 이후 준대형 신차 구입자\n3. 자동차 관련업 종사자 제외\n사전에 차량등록증 사진을 찍어서 보내 주셔야 하니 참고 부탁 드립니다.\n<소요 시간>\n1시간 내외\n<사례비>\n10만원\n<진행 장소>\n서초동 예술의전당 부근\n자세한 사항은 신청자나 문의자에 한해 추가 설명 드리겠습니다.\n내용 확인 하시고 많은 신청 부탁드립니다.\n감사합니다.\n<진행일정>\n10월 9일(금) ~10일(토) / 시간은 추후 안내드립니다\n신청시\n1. 성명, 성별, 연령, 연락처, 거주지역, 직업(구체적),\n2. 현재 댁에 보유하고 있는 총 차량 대수\n3. 현재 보유하고 있는 차량명, 구입시기, 연료타입, 명의자, 명의자와의 관계\n4. 그 중 가장 주로 운행하는 차량을 기재해 주세요.\n5. 주로 이용하시는 차량 바로 직전에 타셨던 차량은 어떤 차량이신가요?\n6. 향후 2년내 구매 의향이신 차량명을 1~3순위 작성해 주세요.\n7. 자녀 연령을 작성해 주세요.\n8. 차량등록증 사진 보내주시는 것에 동의하시나요?\nhttps://forms.gle/nFtPPaxG5Ja1gJ1g6\n좋아요\n0\n송파구에서 핫한 진짜 동네 이야기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.10.01. 18:17 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n만50-69세 남성) 시니어 건강음료 갱서베이\n좌담회알바좌담회카페\n26.10.01.\n댓글\n1\n10/9~10)만 30세~64세 남여) 24년 8월 이후 준대형 신차 구입하신 분\n좌담회알바좌담회카페\n26.10.01.\n댓글\n1\n만 30세~64세 남여) 24년 9월 이후 그랜저 신차 구입하신 분 대상 조사\n좌담회알바좌담회카페\n26.10.01.\n댓글\n1\n10/14) 고급차 차량 이용 패턴 인터뷰2\n좌담회알바좌담회카페\n26.10.01.\n댓글\n1\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n좌담회알바좌담회카페\n 님\n의 글을 3개 보셨네요. 👀\n구독하고 새로운 글을 놓치지 마세요!\n멤버 구독하기\n목록으로\n좋아요\n0\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
