      "title": "~10/22)전국 거주하는 만 25~34세 여성 )박준 뷰티랩/바이오가 트리트먼트 사용자 대상 평가 조사",
      "source": "naver_cafe",
      "source_url": "https://m.cafe.naver.com/togetheralba/129656",
      "target_age": "",
      "target_gender": "",
      "target_condition": "평가 조사",
