      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n~10/22)전국 거주하는 만 25~34세 여성 대상) 프롬랩스 트리트먼트 사용자 대상 평가 조사\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.01. 21:16\n조회 24\n구독\n~10/22)전국 거주하는 만 25~34세 여성 대상) 프롬랩스 트리트먼트 사용자 대상 평가 조사\n■ 대상자 조건:\n**전국 거주하는 만 25~34세 여성 대상\n**프롬팹스 단백질 흡착 트리트먼트 사용자\n■ 조사 일정:\n**제품 수령: 대략 10/8(목)~10/12(월) 예상\n**제품 사용 및 온라인 조사: 대략 10/12(월)~10/22(목) 진행 예정\n※ 반드시 위 일정에 제품을 수령하여 조사 진행이 가능하신 분들만 신청 바랍니다.\n■ 조사 방법:\n-트리트먼트 사용성 평가 조사는 아래와 같이 총 2번의 조사로 나누어 진행됩니다.\n<조사 참여>\n1. (제품 사용 중) 온라인 설문 작성 (총 3번 진행/ 건당 5분 예상)\n2. (제품 사용 후) 사후 평가 작성 (1번 진행/ 10분 예상)\n위와 같이 간단한 온라인 설문으로 진행되며 다이어리는 각 제품을 사용하실 때마다 작성해주셔야 합니다.\n- 샴푸 1종 및 헤어 마스크 3종을 총 11일간 사용하시면서 온라인 조사에 참여합니다.\n- 제품 당 3일 사용 후, 1일 휴지기를 거쳐 다음 제품을 사용합니다.\n사례비는 사용 평가 및 사후 평가에 모두 참여 완료하신 후 담당자 검증을 통해 적립금 30,000원으로 지급됩니다.\n※ 끝까지 성실하게 조사 임해주실 분만 신청 부탁드립니다.\n※ 조사 기간 중에는 기존에 사용하시던 헤어마스크 사용을 중단하고, 발송드리는 조사 제품만 사용해주셔야 합니다.\n※ 제품 사용 기간 동안 샴푸와 헤어마스크 제품만 사용해주시고, 헤어오일, 에센스 등 기타 헤어제품 사용은 불가합니다.\n※ 중요: 참여 도중 중간 탈락 시, 제품 반송이 필수적이며 적립금은 지급되지 않습니다.\n* 신청방법\n※ 이름/ 생년월일/ 성별/ 연락처 작성 후 아래 질문에 응답해주세요\n질문1) 현재 모발 길이를 선택해주세요.\n1. 숏컷 (목선과 뒷목이 드러나는 아주 짧은 기장)\n2. 숏단발 (턱선 근처까지 오는 짧은 기장의 단발)\n3. 단발 (목 중간~어깨에 닿기 전까지 오는 기장의 단발)\n4. 중단발 (어깨에 닿는 정도부터 쇄골까지 내려오는 정도의 기장)\n5. 쇄골~가슴 기장의 장발\n6. 가슴~허리 기장의 장발\n질문2) 현재 사용하고 계신 프롬팹스 단백질 흡착 트리트먼트를 얼마나 자주 사용하고 계십니까?\n1. 매일 사용한다\n2. 일주일에 6회\n3. 일주일에 5회\n4. 일주일에 4회\n5. 일주일에 3회\n6. 일주일에 2회\n7. 일주일에 1회\n8. 그보다 드물게\n질문3) 귀하께서 1년 이내 직접 구입하여 사용해보신 헤어 마스크 제품명을 모두 선택해주세요.\n1. 어노브 딥 데미지 리페어 헤어 마스크\n2. 프롬랩스 단백질 흡착 트리트먼트\n3. 커리쉴 에프터 살롱 케어 헤어팩 트리트먼트\n4. 팬틴 극손상 트리트먼트\n5. 케라시스 케라마이드 극손상 클리닉 트리트먼트\n6. 엘라스틴 아미노 펩타이드 약산성 단백질 헤어팩\n7. 엘라스틴 프로폴리테라 손상 트리트먼트\n8. 팬틴 실키 스무드 케어 트리트먼트\n질문4) 그 중 현재 사용하고 계시는 헤어 마스크 제품명을 모두 기재해주세요.\n질문5) 평소 헤어 마스크를 어디에서 구입하시는지 1~3순위를 기재해주세요. (ex: 올리브영몰 - 1순위)\n1. 올리브영몰 (앱/웹사이트)\n2. 쿠팡\n3. 네이버 쇼핑\n4. 카카오톡 선물하기\n5. 화장품 브랜드몰 (TS몰 등)\n6. 오픈마켓 (G마켓, 11번가 등)\n7. 백화점몰 (SSG/신세계몰, 롯데On, AK몰)\n8. 무신사\n9. 제조사 공식몰 (아모레몰, LG생활건강 등)\n10. 올리브영 매장\n11. 백화점 매장 (신세계, 롯데, 현대 등)\n12. 브랜드 단독 매장/로드샵\n13. 대형마트/창고형 할인매장 등 (이마트, 코스트코 등)\n14. 브랜드 팝업 스토어\n15. 홈쇼핑몰 (GS Shop, CJ온스타일, H-mall, 롯데홈쇼핑)\n16. 라이브방",
