      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n2시간10만) 10/21~28) 20~59세 여성) 가전 조사\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.01. 21:44\n조회 156\n구독\n2시간10만) 10/21~28) 20~59세 남 여) 가전 조사\n좌담회 : 2시간 /사례비 /10만원\n일정: 10월 21일 ~10월 28일 중 하루\n시간 : 4시, 7시 중 한타임\n나이:20~59세 까지 성별 남 여\n장소 : 성수동 인근\n1. 대형 가전 구독서비스 받는 사람: 냉장고 , 세탁기, 건조기, 에어콘, TV,모니터\n2. 관리형 가전 : 정수기. 공기청전기 , 에에드레스, 스타일러, 로봇 청소기\nA: 구독서비스 하는 사람\nB: 직접 구독 중이며 구독에 포함된 케어 서비스를 받는 사람\nC: LG 전자대형가전을 구독하는 사람\nD:구독하는 제품은 없고, 구독을 고려 하다가 제품을 구매한 사람\n3. 모바일 /삼성/APPLE 가입자\nA: 갤럭시 AI구독클럽 또는 삼성케어 서비스 경험이 없고, 최근 12개월 내 첫 삼성 구독으로 가입\nB: 갤럭시 AI구독클럽 또는 삼성 케어 가입, 포함된 케어서비스를 실제 이용경험자\nC: 애플케어 가입 제품을 이용중인자\nD: 삼성 모바일 구독은 없고, 갤럭시 AI, 구독클럽을 고려했으나 일반 구매를 한 사람\n적어주실 내용: 이름 /생년월일/나이 / 전화번호/ 거주지역/ 가구형태/ 하시는일(직업)\n위에 해당하는 것 예시) 1-B (내장고, TV) 혹은 1-C (LG전자 냉장고 , 세탁기, 건조기\nhttps://forms.gle/AyTeYKfvQppJ5c5L8\n10/21~28) 20~59세 남 여) 가전 조사\n010-4648-7146 -- 연락처 사이 하이픈 꼭 챙겨주시구요^^ 하이픈 안챙기시는 분 연락처에 숫자가 한개씩 누락되어서 숫자10개가 옵니다ㅠㅠ 연락처 적으신 후 숫자 11개 모두 적었는지 확인 부탁드립니다^^ 간혹 남의번호 적는분이 계십니다,그사람 아닌데요 하면,굉장히 민망하지요ㅠ 적고나서 확인부탁드립니다~ 해당없는 칸에는 해당없음 또는 점 . 또는 무 로 적어주세요~\nforms.gle\n좋아요\n0\n송파구에서 핫한 진짜 동네 이야기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n10/2~13) 사업체 통신서비스 관련 온라인 설문조사-남성\n좌담회알바좌담회카페\n26.10.01.\n댓글\n0\n2시간10만) 10/21~28) 20~59세 여성) 가전 조사\n좌담회알바좌담회카페\n26.10.01.\n댓글\n0\n2시간10만) 10/21~28) 20~59세 남성) 가전 조사\n좌담회알바좌담회카페\n26.10.01.\n댓글\n0\n11/6~29)*만 4세~만12세 이하 남아 자녀와 함께 동반 설문조사_장난감 관련 대면 설문조사\n좌담회알바좌담회카페\n26.10.01.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
