      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n10/2~13) 사업체 통신서비스 관련 온라인 설문조사-여성\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.01. 22:00\n조회 30\n구독\n10/2~13) 사업체 통신서비스 관련 온라인 설문조사\n사업체를 운영하고 계시는 대표나 직장내 통신서비스 관련 업무를 담당하고 계시는 분들 대상으로 온라인조사를 진행하고 있습니다.하단 조건에 해당되시는 분들이 계시면 신청 부탁드립니다.\n1. 조사방법 : 이메일 조사\n2. 조사기간 : 10/2(금)~10/13(화)일 중 하루 / 시간은 추후 안내드립니다\n3. 조사대상\n1) 사업체를 운영하고 계시는 대표나 직장내 통신서비스 관련 업무를 담당하고 계시는 분\n2) 운영중인 회사나 재직중인 사업체가 인터넷 전용회선을 사용하는 경우\n3) 인터넷 전용회선이란(회사만 단독으로 사용하는 회선으로 통신사의 인터넷망까지 직접 연결하여 계약한 속도 그대로 인터넷을 이용할 수 있도록 속도를 보장하는 기업용 인터넷 접속서비스)\n4. 소요시간 : 5분 이내\n5. 사례비 : 5천원 상당 편의점상품권\n***필요한 사항***\n성명/연락처/이메일주소/재직중이거나 운영중인 회사명/재직중이거나 운영중인 회사의지역/소속부서/재직중인회사의 상시근로자수/재직 중인 회사의 인터넷 전용회선 사용여부/인터넷 전용회선 제공업체/ 제공회사 서비스 상품명\nex)홍길동/010-1234-1234/1004@hanmail.net/(주)홍길동리서치/서울/총무팀/100명/인터넷전용회선 사용/SK브로드밴드/광이더넷\nhttps://forms.gle/wose2NYyevGpaG4u5\n10/2~13) 사업체 통신서비스 관련 온라인 설문조사\n010-4648-7146 -- 연락처 사이 하이픈 꼭 챙겨주시구요^^ 하이픈 안챙기시는 분 연락처에 숫자가 한개씩 누락되어서 숫자10개가 옵니다ㅠㅠ 연락처 적으신 후 숫자 11개 모두 적었는지 확인 부탁드립니다^^ 간혹 남의번호 적는분이 계십니다,그사람 아닌데요 하면,굉장히 민망하지요ㅠ 적고나서 확인부탁드립니다~ 해당없는 칸에는 해당없음 또는 점 . 또는 무 로 적어주세요~\nforms.gle\n좋아요\n0\n송파구에서 핫한 진짜 동네 이야기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n고유링크) 10/13~11/6) 90분 30만) 분야 전문가 인터뷰-호텔·의료·금융 관련 재직자\n좌담회알바좌담회카페\n26.10.01.\n댓글\n0\n10/2~13) 사업체 통신서비스 관련 온라인 설문조사-여성\n좌담회알바좌담회카페\n26.10.01.\n댓글\n0\n10/2~13) 사업체 통신서비스 관련 온라인 설문조사-남성\n좌담회알바좌담회카페\n26.10.01.\n댓글\n0\n2시간10만) 10/21~28) 20~59세 여성) 가전 조사\n좌담회알바좌담회카페\n26.10.01.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
