      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n고유링크) 10/13~11/6) 90분 30만) 분야 전문가 인터뷰-회계·재무 전문가\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.01. 22:10\n조회 46\n구독\n고유링크) 10/13~11/6) 90분 30만) 분야 전문가 인터뷰-회계·재무 전문가\n모집이 마감되면 링크가 열리지 않으니 참고 부탁드립니다 ~\n회계·재무 전문가 // B2B 구독·렌탈 서비스 전문가 // 공공/정부기관 재직자 // 코리빙 운영사 또는 건설현장 사무소 재직자 // 통신,제조 관련 재직자 // 호텔·의료·금융 관련 재직자\n참여조건\n[수도권은 한국리서치 본사에서, 비수도권 거주자는 온라인으로 인터뷰 가능합니다.]\n1.회계·재무 전문가\n회계법인 등에 근무하면서 다양한 기업의 회계/재무/세무 업무의 경험을 가지고 있는 분\n리스 회계를 직접 다뤄본 자 (예: 운용리스 및 금융리스 구분, 매출 인식 기준, 반복매출(구독·렌탈) 수익 인식, 자산·부채의 판단 등 포함 / 2019년 전후 경험 모두 포함)\n2.B2B 구독·렌탈 서비스 전문가\nB2B 실무 3년 이상이며, 구독도입→계약→운영→케어→해지 복수 단계 경험이 있는 분\n3. 공공/정부기관 재직자\n조달·구매·계약·시설·행정·총무 부서 재직자, 또는 기숙사·관사·사택 운영 관리 담당자 및?예산 편성·집행 및 임대·리스 도입 결정 권한 보유자\n4. 코리빙 운영사 또는 건설현장 사무소 재직자\n건설사/시행·시공사/현장사무소의 설비 도입 결정·집행 담당자 및?프로젝트 단위 대량 도입 및 회수·재배치 운영 경험 보유자\n5. 통신,제조 관련 재직자\n제조/IT/통신기업의 사원 숙소, 사업장, 공장 설비 투자 의사결정자 또는?TCO 또는 유지보수 관점의 대량 계약 검토 경험 보유자\n6.호텔·의료·금융 관련 재직자\n호텔·숙박/금융기관/의료기관의 시설·비품 도입 의사결정 관여자 및?정기 리뉴얼·품질 유지 관련 구매 검토 경험 보유자\n조사장소 강남구 논현동 한국리서치 본사 (9호선:언주역)\n조사기간 2026-10-13 ~ 2026-11-06일 중 하루 / 시간은 추후 안내드립니다\n소요시간 1시간 30분\n사례비 300,000원\n조사방법 1시간 30분 인터뷰\n안내사항 각 분야별 전문가를 찾고 있으며 유선으로 참여 조건에 대해 여쭤볼 예정입니다.\n조사 참여 고유링크\nhttps://www.hrc-ms.com/participate/improSurvey/799?refuser=23341&intro=2\n좋아요\n0\n'좋아요'로 마음을 나누세요!\n송파구에서 많이 본 동네소식 보러가기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n고유링크) 10/13~11/6) 90분 30만) 분야 전문가 인터뷰-회계·재무 전문가\n좌담회알바좌담회카페\n26.10.01.\n댓글\n0\n고유링크) 10/13~11/6) 90분 30만) 분야 전문가 인터뷰-B2B 구독·렌탈 서비스 전문가\n좌담회알바좌담회카페\n26.10.01.\n댓글\n0\n고유링크) 10/13~11/6) 90분 30만) 분야 전문가 인터뷰-공공/정부기관 재직자\n좌담회알바좌담회카페\n26.10.01.\n댓글\n0\n고유링크) 10/13~11/6) 90분 30만) 분야 전문가 인터뷰-코리빙 운영사 또는 건설현장 사무소 재직자\n좌담회알바좌담회카페\n26.10.01.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
