      "raw_content": "# # 각 분야 전문가 인터뷰\n*대상조건:\n-수도권 거주자는 한국리서치 본사 대면 참석, 비수도권 거주자는 온라인 인터뷰 가능\n-1. 회계·재무 전문가: 기업 회계/재무/세무 업무 경험자 및 리스 회계(운용/금융리스, 구독·렌탈 수익인식 등)를 직접 다뤄본 분\n-2. B2B 구독·렌탈 서비스 전문가: B2B 실무 3년 이상 및 구독 도입~계약~운영~케어~해지 복수 단계 경험자\n-3. 공공/정부기관 재직자: 조달·구매·계약·시설·총무 부서 재직자, 기숙사/관사 관리자 또는 예산 편성·집행 및 임대·리스 도입 권한자\n-4. 코리빙 운영사 또는 건설현장 재직자: 설비 도입 결정·집행 담당자 및 프로젝트 단위 대량 도입·회수 운영 경험자\n-5. 통신·제조 관련 재직자: 사원 숙소/사업장/공장 설비 투자 의사결정자 또는 TCO/유지보수 대량 계약 검토 경험자\n-6. 호텔·의료·금융 관련 재직자: 시설·비품 도입 의사결정 관여자 및 정기 리뉴얼/품질 유지 구매 검토 경험자\n*일정: 2026년 10월 13일 ~ 11월 6일 중 개별 진행\n*소요시간: 1시간 30분\n*사례비: 300,000원\n*장소: 서울 강남구 논현동 한국리서치 본사 (언주역) / 비수도권 거주자는 온라인 인터뷰 가능\n<신청 방법>아래 신청버튼을 클릭하여 설문응답 진행해주세요. 신청해 주신 내용을 바탕으로 대상자가 되시면 저희가 순차적으로 전화 드립니다. 통화 후 참여 명단에 등록해드리며, 명단에 등록되셔야 참여 가능하니 참고 부탁드립니다.\n참가를 원하시는 분은 아래 버튼을 눌러 신청해 주세요.\n좌담회 신청하기 ➜\n글 탐색\n사업체 통신서비스 관련 온라인 설문조사",
